&lt;p&gt;&lt;span style="font-size:14px"&gt;&lt;span style="font-family:arial nova,arial nova_embeddedfont,arial nova_msfontservice,sans-serif"&gt;The months-long investigation led to the recovery of:&lt;/span&gt;&lt;span style="font-family:arial nova,arial nova_embeddedfont,arial nova_msfontservice,sans-serif"&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
&lt;/div&gt;

&lt;div class="ListContainerWrapper SCXW182284300 BCX0" style="margin: 0px; padding: 0px; user-select: text; -webkit-user-drag: none; -webkit-tap-highlight-color: transparent; position: relative; font-family: &amp;quot;Segoe UI&amp;quot;, &amp;quot;Segoe UI Web&amp;quot;, Arial, Verdana, sans-serif; font-size: 12px; background-color: rgb(255, 255, 255);"&gt;
&lt;ul&gt;
     &lt;li&gt;
     &lt;p&gt;&lt;span style="font-size:14px"&gt;&lt;strong&gt;15 firearms&lt;/strong&gt;&lt;span style="font-family:arial nova,arial nova_embeddedfont,arial nova_msfontservice,sans-serif"&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
     &lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;

&lt;div class="ListContainerWrapper SCXW182284300 BCX0" style="margin: 0px; padding: 0px; user-select: text; -webkit-user-drag: none; -webkit-tap-highlight-color: transparent; position: relative; font-family: &amp;quot;Segoe UI&amp;quot;, &amp;quot;Segoe UI Web&amp;quot;, Arial, Verdana, sans-serif; font-size: 12px; background-color: rgb(255, 255, 255);"&gt;
&lt;ul&gt;
     &lt;li&gt;
     &lt;p&gt;&lt;span style="font-size:14px"&gt;&lt;strong&gt;58 machine-gun conversion devices&lt;/strong&gt;&lt;span style="font-family:arial nova,arial nova_embeddedfont,arial nova_msfontservice,sans-serif"&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
     &lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;

